from typing import List

def separate_paren_groups(paren_string: str) -> List[str]:
    paren_string = paren_string.replace(" ", "")  # Remove spaces from the input string
    distinct_strings = []  # Initialize an empty list to store the distinct strings
    start = 0
    end = 0

    while end < len(paren_string):
        if paren_string[end] == '(':
            count = 1
            end += 1
            while count != 0:
                if paren_string[end] == '(':
                    count += 1
                elif paren_string[end] == ')':
                    count -= 1
                end += 1
            distinct_strings.append(paren_string[start:end])  # Extract each collection using the start and end indices
            start = end

    return distinct_strings  # Return the list of distinct strings

